    // 会话事件通知到站：统一 300ms 去抖 → refreshTick 自增 → ChangeDetailView /
    // DetailLoaded 重渲染（数据源引用全不变）
    await act(async () => {
      lastChannel().push({ ipc: 'sessionEvent' });
    });
    // 重渲染确已发生（转录重查为证：refreshKey 变化驱动重查一次）
