  it('归档 change（source = archive 且 worktree 残留）仍以页面主仓根取数（不碰已清理 worktree）', async () => {
    renderDetail(
      {
        detail: detail({ source: 'archive', worktree: 'C:\\demo\\alpha\\.worktrees\\add-feature' }),
        artifacts: PROPOSAL_ENVELOPES,
