describe('ExploreDetailPane：promote 在飞标记（防重复提交态）', () => {
  it('正向：promote 在飞 → 「启动变更」禁用；落地后复位启用（在飞标记随 promise 收敛）', async () => {
    let resolvePromote: () => void = () => {};
