describe('Explore 路由：onCreated 导航链（清单页 → 详情页首轮，AC-1 / AC-8）', () => {
  it('正向：新话题建档 → list.refresh 后 navigate /explores/<占位名> 携 state.autoPrompt；详情页 auto-send 以 stance + 需求原文发起首轮', async () => {
