    expect(prompt).toContain('调研重试策略的失效边界');
    expect(prompt).toContain('## 笔记定名与落盘');
    expect(prompt).not.toContain('openspec/explores');
    // 无 MissingRecord 闪现
    expect(screen.queryByTestId('explore-detail-missing')).toBeNull();
